"""Stage 10 — Email Input API business logic. Orchestrates preprocessing,
the static baseline, the adaptive model, and privacy-conscious logging for
a single prediction request."""

import time
import uuid

from app.core.state import AppState
from app.ml.preprocessing import preprocess_for_inference
from app.storage.event_log import append_event
from app.storage.privacy import safe_preview

DISCLAIMER = (
    "This prediction is generated by an academic demonstration system. "
    "The static SVM model is a fixed baseline; the adaptive model updates "
    "only after you submit feedback below."
)


def run_prediction(app_state: AppState, subject: str, body: str) -> dict:
    settings = app_state.settings
    email_text = f"{subject} {body}".strip()
    processed_text = preprocess_for_inference(email_text)

    static_result = app_state.static_service.predict(processed_text)
    # Adaptive model owns its own River TFIDF vectorizer — no shared
    # feature matrix with the static SVM (see adaptive_model.py docstring).
    adaptive_result = app_state.adaptive_service.predict(processed_text)

    prediction_id = str(uuid.uuid4())

    app_state.prediction_store.save(prediction_id, {
        "prediction_id": prediction_id,
        "processed_text": processed_text,
        "static_label": static_result["label"],
        "static_model_version": static_result["model_version"],
        "adaptive_label": adaptive_result["label"],
        "adaptive_model_version": adaptive_result["model_version"],
        "feedback_applied": False,
    })

    append_event(settings.predictions_log_path, {
        "event_id": str(uuid.uuid4()),
        "timestamp": time.time(),
        "event_type": "prediction",
        "prediction_id": prediction_id,
        "static_label": static_result["label_name"],
        "adaptive_label": adaptive_result["label_name"],
        "static_model_version": static_result["model_version"],
        "adaptive_model_version": adaptive_result["model_version"],
        **safe_preview(email_text, settings.log_full_email_body),
    })

    return {
        "prediction_id": prediction_id,
        "static_prediction": static_result,
        "adaptive_prediction": adaptive_result,
        "preprocessing_status": "ok",
        "disclaimer": DISCLAIMER,
    }
